android.extraProguardRules:
# v0.7.30 R8 rules — chrani reflection-based kod pri minifikaci

# React Native core
-keep class com.facebook.react.** { *; }
-keep class com.facebook.hermes.** { *; }
-keep class com.facebook.jni.** { *; }
-dontwarn com.facebook.react.**
-dontwarn com.facebook.hermes.**

# Expo modules
-keep class expo.modules.** { *; }
-keep class expo.**Module { *; }
-dontwarn expo.modules.**

# Reanimated (nadstavba puvodni proguard-rules.pro)
-keep class com.swmansion.reanimated.** { *; }
-keep class com.facebook.react.turbomodule.** { *; }

# MapLibre RN
-keep class org.maplibre.** { *; }
-keep class com.mapbox.** { *; }
-dontwarn org.maplibre.**

# expo-sqlite native module
-keep class expo.modules.sqlite.** { *; }

# ML Kit (expo-translate-text)
-keep class com.google.mlkit.** { *; }
-dontwarn com.google.mlkit.**

# Gorhom BottomSheet
-keep class com.gorhom.** { *; }

# Zachovat anotace pro reflection
-keepattributes *Annotation*
-keepattributes Signature
-keepattributes InnerClasses,EnclosingMethod

# Zachovat R.string, R.drawable atd. pouzivane v mainfestu
-keepclassmembers class **.R$* {
    public static <fields>;
}
